"""Scam situations, part 4: accounts, links, apps, attachments, QR codes, tech support, fake shops and similar online scams. See scam_scen_core.py.
fr/rw/sw wording is a DRAFT for review by fluent speakers."""
from scam_scen_core import add
from scam_scen_3 import D, NOPAY, VERIFY, BLOCK, NOCODE, TRUST, PAID

NOLINK = ("Do not click the link or open the file. Go to the official website or app by typing the address yourself.", "Ne cliquez pas sur le lien et n'ouvrez pas le fichier. Allez sur le site ou l'appli officiels en tapant vous-même l'adresse.",
          "Ntukande kuri link cyangwa ngo ufungure dosiye. Jya ku rubuga cyangwa porogaramu yemewe wiyandikira aderesi.", "Usibofye kiungo wala kufungua faili. Nenda kwenye tovuti au programu rasmi kwa kuandika anwani mwenyewe.")
PASSW = ("If you already entered a password, change it now from the official app, turn on two-step verification and sign out of other devices.", "Si vous avez déjà saisi un mot de passe, changez-le maintenant depuis l'appli officielle, activez la double vérification et déconnectez les autres appareils.",
         "Niba waramaze kwandika ijambo ry'ibanga, rihindure ubu muri porogaramu yemewe, fungura kwemeza mu byiciro bibiri ukure izindi telefoni.", "Ukishaweka nenosiri, libadilishe sasa kupitia programu rasmi, washa uthibitishaji wa hatua mbili na utoke kwenye vifaa vingine.")

add("invoice_attachment", "medium", ["ATTACH", "r:\\b(?:immediate payment|overdue|unpaid|past due|payment (?:is )?due|enable (?:content|macros|editing)|open (?:the )?(?:attachment|file|document)|urgent|paiement immediat|impaye|ouvrez|activez|inyemezabwishyu|ishyura|fungura|fungua|lipa|ankara)\\w*"],
    ("Unexpected invoice or document attachment", "Facture ou document en pièce jointe inattendu", "Inyemezabwishyu cyangwa dosiye itunguranye", "Ankara au hati iliyoambatishwa isiyotarajiwa"),
    ("Fake invoices and 'documents' carry malware or a fake login page; opening them or clicking 'enable content' can give attackers control of your computer or email.",
     "Les fausses factures et « documents » contiennent des logiciels malveillants ou une fausse page de connexion ; les ouvrir ou cliquer sur « activer le contenu » peut donner le contrôle de l'ordinateur ou de la messagerie.",
     "Inyemezabwishyu n'inyandiko z'impimbano zirimo malware cyangwa urupapuro rw'impimbano rwo kwinjira; kuzifungura cyangwa gukanda «gufungura ibikubiyemo» bishobora guha abagizi ba nabi ubushobozi kuri mudasobwa cyangwa imeri yawe.",
     "Ankara na «nyaraka» bandia hubeba programu hasidi au ukurasa bandia wa kuingia; kuzifungua au kubofya «washa maudhui» kunaweza kuwapa washambuliaji udhibiti wa kompyuta au barua pepe yako."),
    D(("Do not open it or enable content. Check with the sender through another channel, and confirm the invoice exists in your own records before paying anything.", "Ne l'ouvrez pas et n'activez pas le contenu. Vérifiez avec l'expéditeur par un autre canal et confirmez dans vos propres registres que la facture existe avant de payer.", "Ntukayifungure kandi ntukore «gufungura ibikubiyemo». Genzura n'uwohereje unyuze ku rundi rubuga, wemeze ko inyemezabwishyu iri mu bitabo byawe mbere yo kwishyura.", "Usifungue wala kuwasha maudhui. Hakiki na mtumaji kwa njia nyingine, na thibitisha ankara ipo kwenye rekodi zako kabla ya kulipa."), ("Report it to your IT or email provider as phishing.", "Signalez-la comme hameçonnage à votre service informatique ou fournisseur de messagerie.", "Bimenyeshe ikipe ya IT cyangwa utanga imeri nka phishing.", "Ripoti kwa IT au mtoa barua pepe kama hadaa.")))

add("notification_trap", "medium", ["r:\\b(?:allow|autoriser|emera|ruhusu)\\b", "r:\\b(?:not a robot|human|captcha|robot|prove|verify you|watch|continue|age|download|ntabwo ndi robo|usio roboti|je ne suis pas un robot)\\b"],
    ("'Click Allow to prove you are not a robot' notification trap", "Piège aux notifications « cliquez sur Autoriser pour prouver que vous n'êtes pas un robot »", "Umutego w'ubutumwa bwo «gukanda Emera ngo wemeze ko utari robo»", "Mtego wa arifa «bofya Ruhusu kuthibitisha si roboti»"),
    ("Pressing 'Allow' on a fake robot check gives the website permission to send spam, scam ads and fake alerts to your phone for months.",
     "Appuyer sur « Autoriser » lors d'un faux test de robot donne au site la permission d'envoyer spams, publicités frauduleuses et fausses alertes pendant des mois.",
     "Gukanda «Emera» ku igeragezwa ry'impimbano ry'uko utari robo bihesha urubuga uburenganzira bwo kohereza spam, amatangazo y'uburiganya n'impuruza z'impimbano igihe kirekire.",
     "Kubofya «Ruhusu» kwenye jaribio bandia la roboti kunaipa tovuti ruhusa ya kutuma barua taka, matangazo ya utapeli na arifa bandia kwa miezi."),
    D(("Do not press Allow. Close the page; if it already asked, go to your browser's site settings and remove or block notifications for that site.", "N'appuyez pas sur Autoriser. Fermez la page ; si c'est déjà fait, ouvrez les paramètres du navigateur et bloquez les notifications de ce site.", "Ntukande Emera. Funga urupapuro; niba warabikoze, jya mu migenzo ya browser uhagarike ubutumwa bw'urwo rubuga.", "Usibofye Ruhusu. Funga ukurasa; ikiwa umeshafanya, nenda kwenye mipangilio ya kivinjari na uzuie arifa za tovuti hiyo."), BLOCK))

add("tech_support_alert", "high", ["TECH", ("CALL", "APK", "r:\\b(?:toll[- ]free|helpline|hotline|0800\\d*|support number|numero vert|nimero y'ubufasha|namba ya msaada)\\b")],
    ("Fake virus / tech-support alert", "Fausse alerte virus / assistance technique", "Impuruza y'impimbano ya virusi / ubufasha bwa tekiniki", "Tahadhari bandia ya virusi / msaada wa kiufundi"),
    ("Real security warnings do not list a phone number to call. Fake 'technicians' ask you to install remote-control software, then steal passwords and bank access or charge for useless 'repairs'.",
     "Les vraies alertes de sécurité ne donnent pas de numéro à appeler. Les faux « techniciens » vous font installer un logiciel de contrôle à distance, puis volent mots de passe et accès bancaires ou facturent de fausses « réparations ».",
     "Impuruza nyazo z'umutekano ntizitanga nimero yo guhamagara. «Abatekinisiye» b'impimbano bagusaba gushyiraho porogaramu yo kugenzura kure, hanyuma bakiba amagambo y'ibanga na konti ya banki cyangwa bakakwishyuza «gukosora» kudafite akamaro.",
     "Tahadhari halisi za usalama hazitoi namba ya kupiga. «Mafundi» bandia hukuomba usakinishe programu ya kudhibiti kwa mbali, kisha huiba nywila na ufikiaji wa benki au kukutoza «ukarabati» usio na maana."),
    D(("Do not call the number or install anything. Close the pop-up (restart the browser if it will not close) and run a scan with your own antivirus.", "N'appelez pas le numéro et n'installez rien. Fermez la fenêtre (redémarrez le navigateur si besoin) et lancez une analyse avec votre antivirus.", "Ntuhamagare iyo nimero kandi ntugire icyo ushyiraho. Funga idirishya (ongera utangire browser nibiba ngombwa) ukore isuzuma ukoresheje antivirus yawe.", "Usipige namba wala kusakinisha chochote. Funga dirisha (washa upya kivinjari ikihitajika) na uendeshe skani kwa antivirus yako."), ("If someone already had remote access, switch off the internet, change your passwords from another device and call your bank.", "Si quelqu'un a déjà eu l'accès à distance, coupez Internet, changez vos mots de passe depuis un autre appareil et appelez votre banque.", "Niba hari uwabonye uburenganzira bwa kure, zimya internet, uhindure amagambo y'ibanga ukoresheje indi telefoni uhamagare banki yawe.", "Ikiwa mtu alipata ufikiaji wa mbali, zima intaneti, badilisha nywila kutoka kifaa kingine na upige benki yako."), BLOCK), strong=True)

add("account_security_notice", "high", ["r:\\b(?:facebook|instagram|tiktok|whatsapp|telegram|google|gmail|apple id|icloud|netflix|twitter|linkedin|youtube|paypal|microsoft|outlook|yahoo|snapchat|x account|your page|votre page|konti yawe ya|akaunti yako ya)\\b", "r:\\b(?:suspicious|unusual|violation|violated|copyright|disabled|deleted|restricted|security (?:alert|warning|issue)|login|sign-in|compromised|hacked|policy|appeal|verify|locked|activite suspecte|violation|supprime|restreint|ikibazo cy'umutekano|konti izafungwa|akaunti itafungwa|imezuiliwa)\\w*", ("LINK", "r:\\b(?:click|tap|appeal|verify|confirm|log in|sign in|secure your|cliquez|connectez|kanda|bofya|ingia|thibitisha)\\w*")],
    ("Fake social-media / email account security notice", "Faux avis de sécurité de compte (réseau social / e-mail)", "Ubutumwa bw'impimbano bwo kurinda konti (imbuga nkoranyambaga / imeri)", "Taarifa bandia ya usalama wa akaunti (mitandao ya kijamii / barua pepe)"),
    ("Fake 'violation', 'copyright' or 'suspicious login' notices lead to a copy of the real login page. Typing your password there hands your account to the attacker.",
     "Les faux avis de « violation », « droits d'auteur » ou « connexion suspecte » mènent à une copie de la vraie page de connexion. Saisir votre mot de passe livre le compte à l'attaquant.",
     "Ubutumwa bw'impimbano bwa «kurenga amategeko», «uburenganzira bw'umwanditsi» cyangwa «kwinjira gukemangwa» bukujyana ku rupapuro rusa n'urwukuri rwo kwinjira. Kwandika ijambo ry'ibanga aho ni ugutanga konti.",
     "Taarifa bandia za «ukiukaji», «hakimiliki» au «kuingia kunakotia shaka» hukupeleka kwenye nakala ya ukurasa halisi wa kuingia. Kuandika nywila huko ni kumkabidhi mshambuliaji akaunti."),
    D(NOLINK, PASSW, BLOCK))

add("fake_app_update", "high", ["r:\\b(?:update|upgrade|new version|outdated|expired|latest version|mise a jour|nouvelle version|vugurura|ivugurura|sasisha|toleo jipya)\\w*", "r:\\.apk\\b|\\b(?:apk|app|application|download|install|telecharg\\w+|shyiraho|kuramo|pakua|sakinisha)\\b", "LINK"],
    ("Fake app update or APK download link", "Fausse mise à jour d'appli ou lien de téléchargement APK", "Ivugurura ry'impimbano rya porogaramu cyangwa link yo gukuramo APK", "Sasisho bandia la programu au kiungo cha kupakua APK"),
    ("Apps installed from a link or an APK file outside the official store often contain spyware or banking malware that reads your SMS codes and drains accounts.",
     "Les applis installées via un lien ou un fichier APK hors boutique officielle contiennent souvent un logiciel espion ou bancaire qui lit vos codes SMS et vide vos comptes.",
     "Porogaramu zishyirwaho kuri link cyangwa dosiye ya APK hanze y'iduka ryemewe akenshi zirimo spyware cyangwa malware ya banki isoma kode zawe za SMS ikanasiba konti zawe.",
     "Programu zinazosakinishwa kwa kiungo au faili la APK nje ya duka rasmi mara nyingi huwa na spyware au programu hasidi ya benki inayosoma misimbo ya SMS na kumaliza akaunti."),
    D(("Do not install it. Update apps only from the official store (Play Store / App Store) or inside the app's own settings.", "Ne l'installez pas. Mettez à jour les applis uniquement depuis la boutique officielle (Play Store / App Store) ou depuis les paramètres de l'appli.", "Ntuyishyireho. Vugurura porogaramu gusa mu iduka ryemewe (Play Store / App Store) cyangwa mu migenzo ya porogaramu ubwayo.", "Usiisakinishe. Sasisha programu kutoka duka rasmi (Play Store / App Store) au kwenye mipangilio ya programu yenyewe."), ("If you already installed it, switch to flight mode, uninstall it, change your passwords and PINs from another device and tell your bank.", "Si vous l'avez déjà installée, passez en mode avion, désinstallez-la, changez mots de passe et PIN depuis un autre appareil et prévenez votre banque.", "Niba wayishyizeho, shyira telefoni muri flight mode, uyikureho, uhindure amagambo y'ibanga na PIN ukoresheje indi telefoni ubimenyeshe banki.", "Ikiwa uliisakinisha, weka hali ya ndege, iondoe, badilisha nywila na PIN kutoka kifaa kingine na uiambie benki."), BLOCK), strong=True)

add("apk_invitation", "high", ["r:\\b(?:invit\\w*|wedding|ceremony|party|document|documents|photos?|statement|video|certificate|mariage|ubukwe|ubutumire|harusi|mwaliko|sherehe)\\b", "r:\\.apk\\b|\\bapk\\b|\\binstall\\w*|\\bdownload\\w*|\\bpakua\\w*|\\bsakinish\\w*", "LINK"],
    ("Invitation, photo or document that is really an app to install", "Invitation, photo ou document qui est en réalité une appli à installer", "Ubutumire, ifoto cyangwa inyandiko ni porogaramu ushyiraho", "Mwaliko, picha au hati ambayo kwa kweli ni programu ya kusakinisha"),
    ("A wedding invitation, photo or statement that must be 'installed' is malware. Once installed it can read messages, forward OTP codes and take over your WhatsApp and bank apps.",
     "Une invitation de mariage, photo ou relevé à « installer » est un logiciel malveillant. Installé, il lit vos messages, transfère vos codes OTP et prend le contrôle de WhatsApp et des applis bancaires.",
     "Ubutumire bw'ubukwe, ifoto cyangwa inyandiko isaba «gushyirwaho» ni malware. Imaze gushyirwaho isoma ubutumwa, yohereza kode za OTP ikanafata WhatsApp na porogaramu za banki.",
     "Mwaliko wa harusi, picha au taarifa inayohitaji «kusakinishwa» ni programu hasidi. Ikisakinishwa husoma ujumbe, hupeleka misimbo ya OTP na kuchukua WhatsApp na programu za benki."),
    D(("Do not open or install it. Ask the sender by phone call whether they really sent it; invitations and photos never need an app.", "Ne l'ouvrez pas et ne l'installez pas. Demandez à l'expéditeur par appel s'il l'a vraiment envoyé ; invitations et photos n'exigent jamais d'appli.", "Ntuyifungure cyangwa ngo uyishyireho. Baza uwayohereje kuri telefoni niba ari we koko; ubutumire n'amafoto ntibisaba porogaramu.", "Usifungue wala kusakinisha. Muulize mtumaji kwa simu kama alituma kweli; mialiko na picha hazihitaji programu."), ("If you already installed it, go offline, uninstall it and secure your accounts from another device.", "Si vous l'avez déjà installée, coupez Internet, désinstallez-la et sécurisez vos comptes depuis un autre appareil.", "Niba wayishyizeho, zimya internet, uyikureho kandi urinde konti zawe ukoresheje indi telefoni.", "Ikiwa uliisakinisha, zima mtandao, iondoe na linda akaunti zako kutoka kifaa kingine."), BLOCK), strong=True)

add("hacked_friend_link", "medium", ["r:\\b(?:is this you|look at this|omg|you won't believe|check this out|see what|vote for me|help me vote|watch this|have you seen|c'est toi|regarde|c'est toi dans|ni wowe|reba|urabona|angalia hii|ni wewe|umeona)\\b", "LINK"],
    ("Message from a 'friend' with a strange link (hacked account)", "Message d'un « ami » avec un lien étrange (compte piraté)", "Ubutumwa bw'«inshuti» bufite link idasanzwe (konti yatwawe)", "Ujumbe kutoka kwa «rafiki» wenye kiungo cha ajabu (akaunti iliyodukuliwa)"),
    ("When a friend's account is hacked, the attacker sends the same short, curious message and a link to everyone in their contacts. The link steals logins or installs malware.",
     "Quand le compte d'un ami est piraté, l'attaquant envoie le même court message curieux avec un lien à tous ses contacts. Le lien vole des identifiants ou installe un logiciel malveillant.",
     "Iyo konti y'inshuti yatwawe, umugizi wa nabi yohereza ubutumwa bumwe bugufi butera amatsiko hamwe na link ku bantu bose bayo. Link yiba ijambo ry'ibanga cyangwa ishyiraho malware.",
     "Akaunti ya rafiki ikidukuliwa, mshambuliaji hutuma ujumbe ule ule mfupi wa udadisi na kiungo kwa marafiki wote. Kiungo huiba nywila au husakinisha programu hasidi."),
    D(("Do not click. Call or message your friend on another channel to ask whether they really sent it, and warn them their account may be hacked.", "Ne cliquez pas. Appelez ou écrivez à votre ami sur un autre canal pour demander s'il l'a envoyé et prévenez-le que son compte est peut-être piraté.", "Ntukande. Hamagara cyangwa wandikire inshuti yawe ku rundi rubuga umubaze niba ari yo yohereje, umuburire ko konti ye ishobora kuba yatwawe.", "Usibofye. Mpigie au mwandikie rafiki yako kwa njia nyingine kuuliza kama alituma na umwonye akaunti yake inaweza kuwa imedukuliwa."), NOLINK))

add("qr_code_trap", "high", ["r:\\b(?:qr|scan)\\b", "r:\\b(?:receive|receiving|payment|money|accept|collect|get paid|refund|win|won|recevoir|paiement|argent|encaisser|kwakira|amafaranga|kubona|kupokea|pesa|malipo)\\w*", ("CODE", "r:\\b(?:enter|type|pin|confirm|saisissez|andika|emeza|weka|thibitisha)\\b")],
    ("QR code that 'receives' money but takes it", "Code QR qui « reçoit » de l'argent mais en prend", "QR code «yakira» amafaranga ariko ikayakuramo", "QR code inayodai «kupokea» pesa lakini inachukua"),
    ("You never need to scan a QR code or enter a PIN to RECEIVE money. Scanning to 'accept' a payment actually authorises a payment from you.",
     "Il ne faut jamais scanner un QR code ni saisir un PIN pour RECEVOIR de l'argent. Scanner pour « accepter » un paiement autorise en réalité un paiement de votre part.",
     "Ntabwo ukenera gusikana QR code cyangwa kwandika PIN ngo UKIRE amafaranga. Gusikana ngo «wemere» ubwishyu bisobanura kwemera ko ukurwaho amafaranga.",
     "Huhitaji kamwe kuskani QR code wala kuweka PIN ili UPOKEE pesa. Kuskani ili «kukubali» malipo kwa kweli kunaidhinisha malipo kutoka kwako."),
    D(("Do not scan and never enter your PIN to receive money. Check your balance in the official app; money arrives without any action from you.", "Ne scannez pas et ne saisissez jamais votre PIN pour recevoir de l'argent. Vérifiez votre solde dans l'appli officielle ; l'argent arrive sans action de votre part.", "Ntugasikane kandi ntuzigere wandika PIN ngo ukire amafaranga. Reba amafaranga muri porogaramu yemewe; amafaranga yinjira nta cyo ukoze.", "Usiskani na kamwe usiweke PIN ili kupokea pesa. Angalia salio kwenye programu rasmi; pesa huingia bila hatua yoyote kutoka kwako."), NOCODE, PAID), strong=True)

add("gift_card_codes", "high", ["GIFT", "r:\\b(?:codes?|numbers?|photo|picture|scratch|send|buy|purchase|pay|achetez|envoyez|codes|ohereza|gura|nunua|tuma|toa|lipa)\\w*"],
    ("Payment or request in gift cards / voucher codes", "Paiement ou demande en cartes cadeaux / codes de bons", "Kwishyura cyangwa gusaba mu ikarita z'impano / kode za voucher", "Malipo au ombi kwa kadi za zawadi / misimbo ya vocha"),
    ("No bank, police officer, tax office or employer asks to be paid in gift cards. Gift-card codes are untraceable cash that scammers spend within minutes.",
     "Aucune banque, policier, administration fiscale ou employeur ne demande à être payé en cartes cadeaux. Les codes sont de l'argent intraçable que les escrocs dépensent en quelques minutes.",
     "Nta banki, umupolisi, ikigo cy'imisoro cyangwa umukoresha usaba kwishyurwa mu makarita y'impano. Kode ni amafaranga adashobora gukurikiranwa abatekamutwe bakoresha mu minota mike.",
     "Hakuna benki, polisi, mamlaka ya kodi wala mwajiri anayedai kulipwa kwa kadi za zawadi. Misimbo ni pesa isiyoweza kufuatiliwa ambayo matapeli hutumia ndani ya dakika."),
    D(("Do not buy or send gift cards. If you already did, contact the card issuer at once with the receipts; sometimes the codes can still be frozen.", "N'achetez ni n'envoyez de cartes cadeaux. Si c'est déjà fait, contactez immédiatement l'émetteur avec les reçus ; parfois les codes peuvent encore être gelés.", "Ntugure cyangwa ngo wohereze amakarita y'impano. Niba wamaze kubikora, hamagara uyatanga ako kanya ufite inyemezabwishyu; rimwe na rimwe kode zishobora gufungwa.", "Usinunue wala kutuma kadi za zawadi. Ukishafanya, wasiliana na mtoaji mara moja ukiwa na risiti; wakati mwingine misimbo bado inaweza kuzuiwa."), BLOCK), strong=True)

add("fake_shop_deal", "high", ["r:\\b(?:\\d+ ?% off|brand new|original|sealed|half price|too good|clearance|flash sale|limited stock|iphone|samsung|laptop|ps5|macbook|tv|motorcycle|moto|generator|neuf|prix cadeau|solde|bishya|igiciro gito|punguzo|mpya|bei ya chini|nusu bei)\\b", "r:\\b(?:pay (?:full|all|in advance|first|upfront|before)|full payment|prepay|advance payment|pay now|deposit|payer d'avance|payez avant|paiement integral|banza wishyure|kwishyura mbere|lipa kwanza|malipo ya awali|lipa yote)\\b", "r:\\b(?:deliver\\w*|ship\\w*|livraison|livrer|kugeza|tuzakugezaho|tutatuma|tutakuletea|usafirish\\w*)\\b"],
    ("Too-good-to-be-true online shop or seller (pay first, deliver later)", "Boutique ou vendeur en ligne trop beau pour être vrai (payer d'abord, livrer plus tard)", "Iduka cyangwa ugurisha kuri murandasi uhenze gato cyane (banza wishyure, bazagutwara nyuma)", "Duka au muuzaji mtandaoni wa bei nzuri kupita kiasi (lipa kwanza, tutaleta baadaye)"),
    ("Fake sellers advertise very cheap phones, laptops or goods, ask for full payment first, then block you. Prices far below market and 'pay before delivery' are the two signs.",
     "Les faux vendeurs annoncent téléphones, ordinateurs ou biens très bon marché, exigent le paiement complet d'abord puis vous bloquent. Prix très bas et « payer avant livraison » sont les deux signes.",
     "Abagurisha b'impimbano batangaza telefoni, mudasobwa cyangwa ibindi ku giciro gito cyane, bagasaba ubwishyu bwose mbere hanyuma bakagufunga. Igiciro gito cyane na «wishyure mbere yo gutwarwa» ni ibimenyetso bibiri.",
     "Wauzaji bandia hutangaza simu, kompyuta au bidhaa kwa bei ya chini sana, hudai malipo yote kwanza kisha hukuzuia. Bei ya chini mno na «lipa kabla ya kuletewa» ni dalili mbili."),
    D(("Pay on delivery or meet in person and inspect the item first. Never pay in advance to a stranger or to a personal mobile-money number.", "Payez à la livraison ou rencontrez le vendeur et inspectez l'article d'abord. Ne payez jamais d'avance à un inconnu ni sur un numéro d'argent mobile personnel.", "Ishyura ku gutwarwa cyangwa muhure ubanze usuzume igicuruzwa. Ntukishyure mbere umuntu utazi cyangwa nimero bwite ya mobile money.", "Lipa wakati wa kuletewa au kutana ana kwa ana na ukague bidhaa kwanza. Kamwe usilipe mapema kwa mgeni au namba binafsi ya pesa za simu."), ("Search the seller's name or shop with the word 'scam', and check reviews on more than one site.", "Cherchez le nom du vendeur ou de la boutique avec le mot « arnaque » et lisez les avis sur plusieurs sites.", "Shakisha izina ry'ugurisha cyangwa iduka hamwe n'ijambo «uburiganya» urebe n'ibitekerezo ku mbuga nyinshi.", "Tafuta jina la muuzaji au duka pamoja na neno «utapeli» na uangalie maoni kwenye tovuti zaidi ya moja."), BLOCK))

add("fake_buyer", "high", ["r:\\b(?:buy your|interested in your|i will buy|i want to buy|your (?:laptop|phone|car|ad|item|product|house|advert)|ushaka kugura|nshaka kugura|ninunue|nataka kununua)\\b", "r:\\b(?:courier|my agent|shipping|transport|my driver|customs|pickup|freight|messager|transporteur|umukozi wanjye|ubwikorezi|wakala wangu|usafirishaji)\\b", ("PAY", "FEE", "r:\\b(?:first|before|advance|d'abord|mbere|kwanza)\\b")],
    ("Fake buyer who needs you to pay a courier or fee first", "Faux acheteur qui exige que vous payiez d'abord transporteur ou frais", "Umuguzi w'impimbano ukwishyuza ubwikorezi cyangwa amafaranga mbere", "Mnunuzi bandia anayekutaka ulipe msafirishaji au ada kwanza"),
    ("A 'buyer' who will send money via an agent or courier, and asks YOU to pay a shipping, customs or insurance fee first, never pays. Real buyers pay you directly or in person.",
     "Un « acheteur » qui enverra l'argent via un agent ou transporteur et vous demande de payer d'abord des frais de transport, douane ou assurance ne paiera jamais. Les vrais acheteurs paient directement ou en personne.",
     "«Umuguzi» uzohereza amafaranga binyuze ku mukozi cyangwa ubwikorezi, akagusaba ko ari wowe wishyura mbere amafaranga y'ubwikorezi, amahoro cyangwa ubwishingizi ntazigera yishyura. Abaguzi nyabo bakwishyura ubwabo cyangwa imbonankubone.",
     "«Mnunuzi» atakayetuma pesa kupitia wakala au msafirishaji na kukuomba WEWE ulipe ada ya usafiri, forodha au bima kwanza hatalipa kamwe. Wanunuzi halisi hulipa moja kwa moja au ana kwa ana."),
    D(("Do not pay anything to receive a payment. Hand over the item only after you have confirmed the money in your own account.", "Ne payez rien pour recevoir un paiement. Ne remettez l'article qu'après avoir confirmé l'argent sur votre propre compte.", "Ntukishyure ikintu ngo wakire ubwishyu. Tanga igicuruzwa gusa umaze kwemeza ko amafaranga ari kuri konti yawe.", "Usilipe chochote ili kupokea malipo. Toa bidhaa baada ya kuthibitisha pesa kwenye akaunti yako mwenyewe."), BLOCK))

add("visa_lottery_fee", "high", ["r:\\b(?:green card|visa|dv ?lottery|immigration|usa|canada|permit|work permit|residence|viza|visa lottery|loterie visa|igitsina|kibali)\\b", "r:\\b(?:selected|approved|won|winner|lottery|loterie|chosen|eligible|watoranyijwe|mwatoranyijwe|umeteuliwa|umechaguliwa|mwatsindiye)\\w*", ("PAY", "FEE", "r:\\b(?:application|registration|processing|frais de dossier|ubwishyu bwo kwiyandikisha|ada ya maombi)\\w*")],
    ("Visa or green-card 'lottery' that asks for a fee", "« Loterie » de visa ou carte verte avec frais", "«Tombola» ya viza cyangwa green card isaba amafaranga", "«Bahati nasibu» ya visa au green card inayodai ada"),
    ("Official visa lotteries are free to enter and never contact you by SMS, WhatsApp or private email to ask for payment. Paying 'processing fees' to unofficial agents loses your money.",
     "Les loteries de visa officielles sont gratuites et ne vous contactent jamais par SMS, WhatsApp ou e-mail privé pour demander un paiement. Payer des « frais de traitement » à des agents non officiels fait perdre l'argent.",
     "Tombola nyazo za viza ntizishyuza kandi ntizigera zigutumaho kuri SMS, WhatsApp cyangwa imeri bwite zisaba kwishyura. Kwishyura «amafaranga yo gutunganya» abakozi batemewe ni uguhomba.",
     "Bahati nasibu halisi za visa hazitozwi na hazikutafuti kwa SMS, WhatsApp au barua pepe binafsi kudai malipo. Kulipa «ada za usindikaji» kwa mawakala wasio rasmi ni kupoteza pesa."),
    D(("Do not pay. Check visa programmes only on the official government website of the country concerned, which you type yourself.", "Ne payez pas. Vérifiez les programmes de visa uniquement sur le site officiel du gouvernement concerné, que vous tapez vous-même.", "Ntukishyure. Genzura gahunda za viza gusa ku rubuga rwemewe rwa leta y'igihugu bireba, wiyandikira aderesi.", "Usilipe. Hakiki programu za visa kwenye tovuti rasmi ya serikali ya nchi husika tu, unayoandika mwenyewe."), BLOCK))

add("exam_leak_sale", "high", ["r:\\b(?:exam|examination|national exam|test|paper|papers|ibizamini|ikizamini|mtihani|examen|epreuve)\\w*", "r:\\b(?:leak\\w*|before the exam|answers?|early|advance|guaranteed pass|fuite|corrig\\w*|ibisubizo|kuvuza|maswali ya mapema|majibu|kabla ya mtihani)\\b", ("MONEY", "PAY")],
    ("Exam-paper leak for sale", "Fuite d'épreuves d'examen à vendre", "Kugurisha ibibazo by'ikizamini byavuzwe", "Uuzaji wa karatasi za mtihani zilizovuja"),
    ("Sellers of 'leaked' exam questions usually have nothing and take the money. Even if they did, cheating can cancel your results and bring penalties.",
     "Les vendeurs de sujets « fuités » n'ont en général rien et prennent l'argent. Même s'ils avaient quelque chose, la fraude peut annuler vos résultats et entraîner des sanctions.",
     "Abagurisha ibibazo «byavuzwe» akenshi nta cyo bafite bakajyana amafaranga. Nubwo baba bafite, kwiba ikizamini bishobora gutuma amanota yawe avanwaho ugahanwa.",
     "Wauzaji wa maswali ya mtihani «yaliyovuja» mara nyingi hawana kitu na huchukua pesa. Hata wakiwa nayo, kudanganya kunaweza kufuta matokeo yako na kuleta adhabu."),
    D(("Do not pay or share your details. Prepare with real past papers from your school or the education authority.", "Ne payez pas et ne donnez pas vos données. Préparez-vous avec de vrais anciens sujets de votre école ou de l'autorité éducative.", "Ntukishyure kandi ntugire amakuru utanga. Itegure ukoresheje ibibazo by'imyaka yashize nyabyo biva ku ishuri ryawe cyangwa ikigo cy'uburezi.", "Usilipe wala kutoa taarifa. Jiandae kwa karatasi halisi za miaka iliyopita kutoka shuleni au mamlaka ya elimu."), BLOCK))

add("free_data_chain", "medium", [("FREE", "WIN"), "r:\\b(?:data|airtime|gb|mb|bundles?|internet|credit|forfait|minutes|amasaha|dakika|vifurushi|megabytes)\\b", "r:\\b(?:share|forward|friends|groups?|click|link|\\d+ (?:people|friends|groups|contacts)|partagez|transferez|ohereza|sangiza|tuma|sambaza|marafiki)\\w*"],
    ("Free data / airtime message that must be forwarded", "Message de données / crédit gratuits à transférer", "Ubutumwa bwa data / airtime ku buntu busaba kubwohereza ku bandi", "Ujumbe wa data / muda wa maongezi wa bure unaohitaji kusambazwa"),
    ("Free-data chains are bait: forwarding them spreads the scam and the link steals your details or signs you up for paid services. Operators announce offers in their own app and official channels.",
     "Les chaînes de « données gratuites » sont un appât : les transférer propage l'arnaque et le lien vole vos données ou vous abonne à des services payants. Les opérateurs annoncent leurs offres dans leur appli et canaux officiels.",
     "Ubutumwa bwa data ku buntu ni urushinge: kububohereza bikwirakwiza uburiganya kandi link yiba amakuru yawe cyangwa igushyira muri serivisi zishyurwa. Sosiyete zitangaza amaturo yazo muri porogaramu zazo no mu nzira zemewe.",
     "Misururu ya data ya bure ni chambo: kuisambaza huenea utapeli na kiungo huiba taarifa zako au kukujiandikisha kwenye huduma za kulipia. Kampuni hutangaza ofa kwenye programu na njia zao rasmi."),
    D(("Do not forward or click. Check offers only in your operator's official app or through its official short code.", "Ne transférez pas et ne cliquez pas. Vérifiez les offres uniquement dans l'appli officielle de l'opérateur ou son code court officiel.", "Ntukohereze kandi ntukande. Genzura amaturo gusa muri porogaramu yemewe ya sosiyete cyangwa kode yayo ngufi yemewe.", "Usisambaze wala kubofya. Hakiki ofa kwenye programu rasmi ya kampuni au msimbo wake rasmi mfupi tu."), BLOCK))

add("subscription_trap", "high", [("WIN", "FREE", "r:\\b(?:prize|gift|cadeau|zawadi|ibihembo)\\b"), "r:\\b(?:enter|send|your number|phone number|text|reply|confirm|sms|short ?code|saisissez|envoyez|andika|ohereza|weka namba|tuma)\\w*", "r:\\b(?:per day|daily|charged|billed|subscription|weekly|every (?:day|week)|par jour|abonnement|chaque jour|buri munsi|kila siku|usajili|ibyumweru|ugunduke)\\b"],
    ("'Free' prize or trial that secretly signs you up to a paid subscription", "Gain ou essai « gratuit » qui vous abonne en secret à un service payant", "Igihembo cyangwa igeragezwa «ku buntu» rigushyira rwihishwa muri serivisi yishyurwa", "Zawadi au jaribio «bure» linalokujiandikisha kwa siri kwenye usajili wa kulipia"),
    ("Entering your number on a 'free prize' page can subscribe you to a premium service that charges every day from your airtime or mobile money.",
     "Saisir votre numéro sur une page de « gain gratuit » peut vous abonner à un service premium débité chaque jour de votre crédit ou argent mobile.",
     "Kwandika nimero yawe ku rupapuro rwa «igihembo ku buntu» bishobora kugushyira muri serivisi ya premium ikuramo amafaranga buri munsi ku airtime cyangwa mobile money.",
     "Kuweka namba yako kwenye ukurasa wa «zawadi bure» kunaweza kukujiandikisha kwenye huduma ya premium inayotoza kila siku kutoka muda wa maongezi au pesa za simu."),
    D(("Do not enter your number or reply. If you may already be subscribed, send STOP to the sender and ask your operator to block premium services on your line.", "Ne saisissez pas votre numéro et ne répondez pas. Si vous êtes peut-être déjà abonné, envoyez STOP à l'expéditeur et demandez à l'opérateur de bloquer les services premium.", "Ntukandike nimero yawe kandi ntusubize. Niba wenda kuba waramaze kwiyandikisha, ohereza STOP uwohereje usabe sosiyete guhagarika serivisi za premium.", "Usiweke namba yako wala kujibu. Kama huenda umeshajiandikisha, tuma STOP kwa mtumaji na uombe kampuni kuzuia huduma za premium."), BLOCK))

add("domain_renewal_invoice", "medium", ["r:\\b(?:domain|website|hosting|seo|trademark|directory|listing|nom de domaine|site web|domaine|urubuga|izina rya domaine|tovuti|kikoa)\\b", "r:\\b(?:expire\\w*|expir\\w*|renew\\w*|renouvel\\w*|invoice|suspend\\w*|facture|ivugurura|kongera|kuvugurura|isha|inaisha|upya)\\b", ("MONEY", "PAY")],
    ("Fake domain / website renewal invoice", "Fausse facture de renouvellement de domaine / site web", "Inyemezabwishyu y'impimbano yo kuvugurura domaine / urubuga", "Ankara bandia ya kuhuisha kikoa / tovuti"),
    ("Scammers send invoices for 'domain expiry' or 'SEO listing' from companies you never used, counting on busy owners to pay without checking their real registrar.",
     "Des escrocs envoient des factures d'« expiration de domaine » ou d'« inscription SEO » de sociétés que vous n'avez jamais utilisées, en comptant sur des propriétaires pressés de payer sans vérifier.",
     "Abatekamutwe bohereza inyemezabwishyu za «domaine irangiye» cyangwa «urutonde rwa SEO» z'ibigo utigeze ukoresha, biringiye ko ba nyir'ubucuruzi bihuta bakishyura batagenzuye.",
     "Matapeli hutuma ankara za «kikoa kinaisha» au «orodha ya SEO» kutoka kampuni usizotumia, wakitegemea wamiliki wenye shughuli walipe bila kukagua."),
    D(("Do not pay. Log in to your real domain registrar or hosting account (typing its address yourself) and check the expiry date there.", "Ne payez pas. Connectez-vous à votre vrai registraire ou hébergeur (en tapant l'adresse vous-même) et vérifiez-y la date d'expiration.", "Ntukishyure. Injira kuri konti yawe nyayo y'aho wanditse domaine cyangwa hosting (wiyandikira aderesi) ugenzure itariki irangiriraho.", "Usilipe. Ingia kwenye msajili au mwenyeji wako halisi (ukiandika anwani mwenyewe) na uangalie tarehe ya kuisha huko."), VERIFY))

add("fake_gov_portal", "high", ["r:\\b(?:renew|apply|register|passport|driving licen[cs]e|permit|visa|tax|nida|id card|certificate|irembo|licen[cs]e|e-?citizen|renouvel\\w*|permis|passeport|gusaba|kuvugurura|kuhindura|leseni|pasipoti|kitambulisho)\\b", "LINK", "r:\\b(?:enter|card|pin|id number|payment|pay|fee|login|log in|saisissez|carte|paiement|andika|ikarita|kwishyura|weka|kadi|lipa|ingia)\\w*"],
    ("Fake government service website (Irembo, licence, ID, permit)", "Faux site de service public (Irembo, permis, pièce d'identité)", "Urubuga rw'impimbano rwa serivisi za leta (Irembo, uruhushya, indangamuntu)", "Tovuti bandia ya huduma za serikali (Irembo, leseni, kitambulisho)"),
    ("Look-alike government portals collect ID numbers, card details and 'fees'. Government services use official addresses ending in .gov.rw (or the country's official domain) and never ask for card PINs.",
     "Les faux portails publics collectent numéros d'identité, données de carte et « frais ». Les services publics utilisent des adresses officielles en .gov.rw (ou le domaine officiel du pays) et ne demandent jamais de PIN de carte.",
     "Imbuga z'impimbano zisa n'iza leta zikusanya nimero z'indangamuntu, amakuru y'ikarita n'«amafaranga». Serivisi za leta zikoresha aderesi zemewe zirangirira kuri .gov.rw (cyangwa domaine yemewe y'igihugu) kandi ntizisaba PIN y'ikarita.",
     "Tovuti bandia za serikali hukusanya namba za kitambulisho, taarifa za kadi na «ada». Huduma za serikali hutumia anwani rasmi zinazoishia .gov.rw (au kikoa rasmi cha nchi) na hazidai PIN ya kadi."),
    D(("Do not enter any details. Type the official service address yourself (for example irembo.gov.rw) or use the official app, and compare it with the link you received.", "Ne saisissez aucune donnée. Tapez vous-même l'adresse officielle du service (par exemple irembo.gov.rw) ou utilisez l'appli officielle et comparez avec le lien reçu.", "Ntukandike amakuru yose. Wiyandikire aderesi yemewe ya serivisi (urugero irembo.gov.rw) cyangwa ukoreshe porogaramu yemewe, ugereranye na link wahawe.", "Usiweke taarifa yoyote. Andika mwenyewe anwani rasmi ya huduma (mfano irembo.gov.rw) au tumia programu rasmi na ulinganishe na kiungo ulichopewa."), PASSW, BLOCK))

add("toll_fine_link", "high", ["r:\\b(?:toll|parking|speeding|traffic fine|road|ticket|plaza|infraction|fine|amende|faini|contravention|rra|police|ihazabu)\\b", "LINK", "r:\\b(?:unpaid|overdue|late fee|due|pay|avoid|outstanding|impaye|payer|eviter|ntiwishyuye|ishyura|usilipe|lipa|bado hujalipa)\\w*"],
    ("Unpaid toll / traffic fine text with a payment link", "SMS de péage / amende impayé avec lien de paiement", "SMS ya amande cyangwa ubwishyu bw'umuhanda butishyuwe ifite link yo kwishyura", "SMS ya faini au ushuru wa barabara ambao haujalipwa na kiungo cha kulipa"),
    ("A text about an unpaid toll or fine with a payment link is a very common phishing wave. Real fines are issued by official bodies and paid through official systems, not through a link in an SMS.",
     "Un SMS de péage ou d'amende impayés avec lien de paiement est une vague d'hameçonnage très courante. Les vraies amendes viennent d'organismes officiels et se paient via des systèmes officiels, pas un lien SMS.",
     "SMS ivuga amande cyangwa ubwishyu bw'umuhanda butishyuwe ifite link yo kwishyura ni umuhengeri usanzwe cyane wa phishing. Amande nyayo atangwa n'ibigo byemewe akishyurwa mu buryo bwemewe, si link ya SMS.",
     "SMS kuhusu faini au ushuru ambao haujalipwa yenye kiungo cha malipo ni wimbi la kawaida sana la hadaa. Faini halisi hutolewa na mamlaka rasmi na kulipwa kwa mifumo rasmi, si kiungo cha SMS."),
    D(NOLINK, ("Check for fines only on the official government system or by calling the official traffic office.", "Vérifiez les amendes uniquement sur le système officiel ou en appelant le bureau officiel de la circulation.", "Genzura amande gusa kuri sisitemu yemewe ya leta cyangwa uhamagare ibiro bya polisi y'umuhanda bwemewe.", "Hakiki faini kwenye mfumo rasmi wa serikali tu au kwa kupiga ofisi rasmi ya trafiki."), BLOCK))

add("wallet_kyc", "high", ["r:\\b(?:wallet|momo|airtel money|mpesa|m-pesa|pochi|tigo pesa|orange money|portefeuille|konti ya momo|mobile money)\\b", "r:\\b(?:kyc|verif\\w+|update|expire\\w*|closure|close|deactivat\\w*|limit\\w*|restricted|suspend\\w*|blocked|validation|guhindura|gufunga|kuzimwa|kusasisha|kufungwa)\\b", ("CODE", "LINK")],
    ("Mobile-money wallet 'KYC / verification' scare", "Alerte « KYC / vérification » du portefeuille d'argent mobile", "Gutera ubwoba kuri «KYC / kwemeza» konti ya mobile money", "Hofu ya «KYC / uthibitisho» ya pochi ya pesa za simu"),
    ("Scammers claim your wallet will be closed or limited unless you 'verify' by sharing your PIN, a code or a link. The real KYC is done in the operator's app or at an agent shop, never by sending your PIN.",
     "Les escrocs disent que votre portefeuille sera fermé ou limité sauf si vous « vérifiez » en donnant votre PIN, un code ou via un lien. Le vrai KYC se fait dans l'appli de l'opérateur ou en boutique, jamais en envoyant votre PIN.",
     "Abatekamutwe bavuga ko konti yawe izafungwa cyangwa igabanywe nutemeje utanze PIN, kode cyangwa unyuze kuri link. KYC nyayo ikorerwa muri porogaramu ya sosiyete cyangwa ku biro, ntibigera bisaba PIN.",
     "Matapeli hudai pochi yako itafungwa au kupunguzwa usipo«thibitisha» kwa kutoa PIN, msimbo au kiungo. KYC halisi hufanywa kwenye programu ya kampuni au duka la wakala, kamwe si kwa kutuma PIN."),
    D(("Do not send your PIN or open the link. Check your wallet status in the official app or ask at an official agent shop.", "N'envoyez pas votre PIN et n'ouvrez pas le lien. Vérifiez l'état du portefeuille dans l'appli officielle ou demandez dans une boutique officielle.", "Ntugire PIN wohereza kandi ntufungure link. Reba uko konti imeze muri porogaramu yemewe cyangwa ubaze ku biro byemewe.", "Usitume PIN wala kufungua kiungo. Angalia hali ya pochi kwenye programu rasmi au uliza kwenye duka rasmi la wakala."), NOCODE, PAID), strong=True)

add("crypto_airdrop_claim", "high", ["r:\\b(?:airdrop|claim|free tokens?|connect (?:your )?wallet|walletconnect|metamask|trust wallet|nft mint|token sale|presale|reclamez|jetons gratuits|kuyaka|ibiceri by'ubuntu|dai|tokeni za bure)\\b", "LINK", "r:\\b(?:connect|claim|approve|sign|reclamez|connectez|kanda|bofya|thibitisha|saini|dai)\\w*"],
    ("Crypto airdrop / 'connect your wallet' claim link", "Lien d'airdrop crypto / « connectez votre portefeuille »", "Link y'airdrop ya crypto / «huza wallet yawe»", "Kiungo cha airdrop ya crypto / «unganisha pochi yako»"),
    ("Fake airdrops and mint pages ask you to connect your wallet and 'approve' a transaction that hands over all your tokens. A free-token link you did not ask for is a trap.",
     "Les faux airdrops et pages de mint demandent de connecter votre portefeuille et d'« approuver » une transaction qui cède tous vos jetons. Un lien de jetons gratuits non demandé est un piège.",
     "Airdrop z'impimbano n'impapuro za mint zigusaba guhuza wallet yawe no «kwemeza» igikorwa gitanga token zawe zose. Link y'ibiceri by'ubuntu utasabye ni umutego.",
     "Airdrop bandia na kurasa za mint hukuomba uunganishe pochi yako na «uidhinishe» muamala unaokabidhi tokeni zako zote. Kiungo cha tokeni za bure ulizoziomba ni mtego."),
    D(("Do not connect your wallet or sign anything. If you already did, move your assets to a new wallet and revoke the token approvals right away.", "Ne connectez pas votre portefeuille et ne signez rien. Si c'est fait, déplacez vos actifs vers un nouveau portefeuille et révoquez les autorisations tout de suite.", "Ntuhuze wallet yawe kandi ntusinye ikintu. Niba warabikoze, kuramo ibyo utunze ubishyire kuri wallet nshya uhagarike uburenganzira wahaye.", "Usiunganishe pochi yako wala kusaini chochote. Ikiwa umeshafanya, hamisha mali zako kwenye pochi mpya na ubatilishe idhini mara moja."), BLOCK), strong=True)

add("pig_butchering", "high", ["r:\\b(?:trader|platform|mentor|analyst|insider|signals?|my (?:uncle|aunt|teacher|friend|mentor)|investment app|plateforme|mentor|umwarimu|uruhushya|jukwaa|mshauri)\\b", "r:\\b(?:make|earn|profit|returns?|win|gain|income|daily|gagner|gains|inyungu|nunguka|faida|pata)\\w*", "r:\\b(?:deposit|usdt|bitcoin|crypto|start with|join|invest|depot|shyiramo|gutangira|weka|anza na)\\w*"],
    ("Online 'mentor' and trading platform (slow investment scam)", "« Mentor » en ligne et plateforme de trading (arnaque à l'investissement lente)", "«Umujyanama» wo kuri murandasi n'urubuga rwo gucuruza (uburiganya bw'ishoramari bukorwa buhoro)", "«Mshauri» wa mtandaoni na jukwaa la biashara (utapeli wa uwekezaji wa polepole)"),
    ("A friendly stranger shows 'profits' on a platform you cannot verify, lets small withdrawals work, then encourages bigger deposits. When you try to withdraw, new fees or 'taxes' appear and the money is gone.",
     "Un inconnu sympathique montre des « profits » sur une plateforme invérifiable, laisse passer de petits retraits puis pousse à déposer plus. Au moment de retirer, de nouveaux frais ou « taxes » apparaissent et l'argent a disparu.",
     "Umuntu utazi w'urugwiro akwereka «inyungu» ku rubuga utabasha kugenzura, akemera kugusubiza amafaranga make, hanyuma agahatira gushyiramo menshi. Nushaka kuyakuramo hazamo andi mafaranga cyangwa «imisoro» amafaranga yawe akayoyoka.",
     "Mgeni rafiki hukuonyesha «faida» kwenye jukwaa usiloweza kuthibitisha, hukuruhusu kutoa kidogo kisha hukusukuma kuweka zaidi. Ukijaribu kutoa, ada au «kodi» mpya huonekana na pesa zimepotea."),
    D(("Stop sending money. Test the platform by asking to withdraw everything; if new fees appear, it is a scam. Do not move to other apps or keep it secret from family.", "Cessez d'envoyer de l'argent. Testez en demandant à tout retirer ; si de nouveaux frais apparaissent, c'est une arnaque. Ne passez pas à d'autres applis et n'en faites pas un secret pour votre famille.", "Hagarika kohereza amafaranga. Gerageza gukuramo ibyose; nihaboneka andi mafaranga, ni uburiganya. Ntukimukire ku zindi porogaramu cyangwa ngo ubigire ibanga ku muryango.", "Acha kutuma pesa. Jaribu kutoa zote; ada mpya zikitokea ni utapeli. Usihamie programu nyingine wala kuficha familia."), TRUST, BLOCK))

add("ponzi_referral", "high", [("INVEST", "r:\\b(?:returns?|monthly|weekly|profit|interest|inyungu|faida|rendement|gains)\\b"), "r:\\b(?:recruit\\w*|refer\\w*|invite|friends|downline|bonus|bring|commission|parrain\\w*|inviter|amis|tumira|uzane|inshuti|waalike|marafiki|leta)\\b", ("PAY", "r:\\b(?:entry fee|join|membership|package|adhesion|kwinjira|kujiunga|uanachama|kifurushi)\\b")],
    ("Ponzi / referral investment scheme", "Système de Ponzi / investissement par parrainage", "Gahunda ya Ponzi / ishoramari rishingiye ku gushaka abandi", "Mpango wa Ponzi / uwekezaji unaotegemea kuleta wengine"),
    ("Ponzi schemes pay old members with the money of new ones and reward recruiting. They always collapse, and the last members lose everything.",
     "Les systèmes de Ponzi paient les anciens avec l'argent des nouveaux et récompensent le recrutement. Ils s'effondrent toujours et les derniers membres perdent tout.",
     "Gahunda za Ponzi zishyura abakera amafaranga y'abashya kandi zihemba gushaka abandi. Ziraseswa buri gihe, abaheruka bagatakaza byose.",
     "Mipango ya Ponzi hulipa wanachama wa zamani kwa pesa za wapya na kutuza kuajiri. Huanguka daima, na wa mwisho hupoteza kila kitu."),
    D(("Do not join or recruit friends. Check that the company holds a licence from the financial regulator before investing a single franc.", "Ne rejoignez pas et ne recrutez pas d'amis. Vérifiez que l'entreprise est agréée par le régulateur financier avant d'investir un seul franc.", "Ntujyemo kandi ntushakishe inshuti. Genzura ko ikigo gifite uruhushya rw'ikigo gishinzwe imari mbere yo gushora ifaranga na rimwe.", "Usijiunge wala kuajiri marafiki. Hakiki kampuni ina leseni ya mdhibiti wa fedha kabla ya kuwekeza hata senti moja."), TRUST, BLOCK))

add("managed_forex", "high", ["r:\\b(?:forex|fx|binary options?|trading account|signals?|copy trad\\w*|options binaires)\\b", "r:\\b(?:manage\\w*|handle|double|multiply|guarantee\\w*|expert|broker|garanti\\w*|gerer|doubler|nzagukorera|nzakwongerera|nitafanya|nitakuongezea|hakika)\\b", ("MONEY", "PAY", "r:\\b(?:deposit|depot|shyiramo|weka)\\w*")],
    ("Forex / trading 'manager' who promises to grow your money", "« Gestionnaire » forex / trading qui promet de faire fructifier votre argent", "«Umucungamutungo» wa forex / ucuruza uvuga ko azakongerera amafaranga yawe", "«Meneja» wa forex / biashara anayeahidi kuzidisha pesa zako"),
    ("People who say they will trade your money for guaranteed profit usually just keep it. Real investment managers are licensed, cannot guarantee profits and never ask you to send money to a personal account.",
     "Ceux qui disent faire fructifier votre argent avec un profit garanti le gardent en général. Les vrais gestionnaires sont agréés, ne garantissent aucun profit et ne demandent jamais d'argent sur un compte personnel.",
     "Abavuga ko bazakorera amafaranga yawe inyungu irizewe akenshi bayigumana. Abacungamutungo nyabo bafite uruhushya, ntibasezeranya inyungu kandi ntibasaba amafaranga kuri konti bwite.",
     "Wanaosema watafanyia pesa zako biashara kwa faida ya uhakika mara nyingi huzibaki nazo. Mameneja halisi wana leseni, hawahakikishii faida na hawaombi pesa kwenye akaunti binafsi."),
    D(("Do not deposit with any individual. Check that the broker is licensed by the financial regulator, and never share your trading password.", "Ne déposez rien chez un particulier. Vérifiez que le courtier est agréé par le régulateur financier et ne partagez jamais votre mot de passe de trading.", "Ntugire amafaranga ushyira ku muntu ku giti cye. Genzura ko broker afite uruhushya rw'ikigo gishinzwe imari kandi ntuzigere ugira undi ijambo ry'ibanga rya trading.", "Usiweke pesa kwa mtu binafsi. Hakiki broker ana leseni ya mdhibiti wa fedha na kamwe usishiriki nywila ya biashara."), BLOCK))

add("escrow_release_fee", "high", ["r:\\b(?:escrow|release fee|clearance (?:fee|certificate)|holding|funds (?:on hold|are held|pending)|safe-?pay|payment (?:is )?pending|sequestre|bloque|amafaranga afashwe|pesa zimeshikiliwa)\\b", ("FEE", "PAY"), "r:\\b(?:release|unlock|activate|clear|withdraw|debloquer|activer|fungura|kuyakura|fungua|toa)\\w*"],
    ("Fake escrow or 'release fee' to unlock a payment", "Faux séquestre ou « frais de déblocage » pour libérer un paiement", "Escrow y'impimbano cyangwa «amafaranga yo gufungura» ubwishyu", "Escrow bandia au «ada ya kufungua» malipo"),
    ("A 'buyer' says their payment is stuck in escrow and you must pay a release fee. The escrow is fake and the buyer never paid.",
     "Un « acheteur » dit que son paiement est bloqué en séquestre et que vous devez payer des frais de déblocage. Le séquestre est faux et l'acheteur n'a rien payé.",
     "«Umuguzi» avuga ko ubwishyu bwe bwafatiriwe muri escrow ko ugomba kwishyura amafaranga yo kubufungura. Escrow ni impimbano kandi umuguzi nta cyo yishyuye.",
     "«Mnunuzi» anasema malipo yake yamekwama escrow na lazima ulipe ada ya kuachilia. Escrow ni bandia na mnunuzi hajalipa chochote."),
    D(("Do not pay a release fee. Check your own account: if the money is not there, nothing was paid. Deal only through payment services you know and use yourself.", "Ne payez pas de frais de déblocage. Vérifiez votre compte : si l'argent n'y est pas, rien n'a été payé. Utilisez seulement des services de paiement que vous connaissez et utilisez vous-même.", "Ntukishyure amafaranga yo gufungura. Reba konti yawe: niba amafaranga atarimo, nta cyo cyishyuwe. Koresha gusa serivisi z'ubwishyu uzi kandi wiyandikishijeho.", "Usilipe ada ya kuachilia. Angalia akaunti yako: pesa zisipokuwepo, hakuna kilicholipwa. Fanya biashara kupitia huduma za malipo unazozijua na kuzitumia mwenyewe."), BLOCK), strong=True)

add("customer_care_code", "high", ["SUPPORT", "CODE", "r:\\b(?:fix|problem|block\\w*|issue|sync|upgrade|suspend\\w*|verify|sorted|resolve|probleme|resoudre|kosora|kibazo|tatizo|suluhisha|rekebisha)\\w*"],
    ("Fake customer care asking for your code or PIN", "Faux service client demandant votre code ou PIN", "Serivisi z'abakiriya z'impimbano zisaba kode cyangwa PIN", "Huduma bandia kwa wateja inayoomba msimbo au PIN"),
    ("Real customer care never asks for your PIN, password or the SMS code sent to you. A code you read out lets them log in as you or approve a payment.",
     "Un vrai service client ne demande jamais votre PIN, mot de passe ou le code SMS reçu. Un code lu à voix haute leur permet de se connecter à votre place ou d'approuver un paiement.",
     "Serivisi nyazo z'abakiriya ntizisaba PIN, ijambo ry'ibanga cyangwa kode ya SMS wahawe. Kode uvuze ibahesha kwinjira nkawe cyangwa kwemeza ubwishyu.",
     "Huduma halisi kwa wateja hazioombi PIN, nenosiri au msimbo wa SMS uliotumiwa. Msimbo unaoutaja huwaruhusu kuingia kama wewe au kuidhinisha malipo."),
    D(("Hang up or stop replying. Call the official customer-care number printed on your card, SIM pack or website that you find yourself.", "Raccrochez ou cessez de répondre. Appelez le numéro officiel du service client imprimé sur votre carte, paquet SIM ou site que vous trouvez vous-même.", "Kata telefoni cyangwa uhagarike gusubiza. Hamagara nimero yemewe y'abakiriya iri ku ikarita, ku ipaki ya SIM cyangwa ku rubuga wishakiye.", "Kata simu au acha kujibu. Piga namba rasmi ya huduma kwa wateja iliyochapishwa kwenye kadi, kifurushi cha SIM au tovuti uliyoitafuta mwenyewe."), NOCODE, PAID), strong=True)

add("card_block_call", "high", ["r:\\b(?:card|carte|ikarita|kadi)\\b", "r:\\b(?:used abroad|blocked|suspicious|unauthori[sz]ed|transaction|fraud|declined|utilisee a l'etranger|bloquee|inhabituelle|yakoreshejwe|imefungwa|ikorwa|isiyo ya|miamala)\\w*", "r:\\b(?:call|give|cvv|card number|pin|confirm|appelez|donnez|numero de carte|hamagara|mpa|nimero y'ikarita|piga|toa|namba ya kadi)\\w*"],
    ("Fake card-fraud alert asking you to call or give card details", "Fausse alerte de fraude à la carte vous demandant d'appeler ou de donner vos données", "Impuruza y'impimbano y'uburiganya ku ikarita igusaba guhamagara cyangwa gutanga amakuru", "Tahadhari bandia ya udanganyifu wa kadi inayokuomba upige au utoe taarifa"),
    ("Scammers text about 'unusual card use' so you call their number or give your card number and CVV, which they use at once to spend your money.",
     "Des escrocs envoient un SMS sur une « utilisation inhabituelle de carte » pour que vous appeliez leur numéro ou donniez numéro et CVV, qu'ils utilisent aussitôt pour dépenser votre argent.",
     "Abatekamutwe bohereza ubutumwa kuri «gukoresha ikarita bidasanzwe» kugira ngo uhamagare nimero yabo cyangwa utange nimero n'CVV, bakabikoresha ako kanya bakoresha amafaranga yawe.",
     "Matapeli hutuma ujumbe kuhusu «matumizi yasiyo ya kawaida ya kadi» ili upige namba yao au utoe namba ya kadi na CVV, wanazozitumia mara moja kutumia pesa zako."),
    D(("Do not call the number in the message or give card details. Use the number on the back of your card or the bank's official app to check recent transactions.", "N'appelez pas le numéro du message et ne donnez aucune donnée de carte. Utilisez le numéro au dos de la carte ou l'appli officielle de la banque pour vérifier les opérations.", "Ntuhamagare nimero iri mu butumwa kandi ntugire amakuru y'ikarita utanga. Koresha nimero iri inyuma y'ikarita cyangwa porogaramu yemewe ya banki urebe ibikorwa biheruka.", "Usipige namba iliyomo kwenye ujumbe wala kutoa taarifa za kadi. Tumia namba iliyo nyuma ya kadi au programu rasmi ya benki kuangalia miamala ya hivi karibuni."), NOCODE, PAID))

add("password_reset_phish", "medium", ["r:\\b(?:password reset|reset your password|verification code|login code|2fa|security code|code de connexion|reinitialis\\w+|kode yo kwinjira|msimbo wa kuingia|badilisha nenosiri)\\b", "r:\\b(?:you (?:didn'?t|did not) request|if this wasn'?t you|someone tried|unrecogni[sz]ed|not you|vous n'avez pas demande|si ce n'est pas vous|niba atari wowe|kama si wewe|mtu amejaribu)\\b", ("LINK", "r:\\b(?:click|call|reply|cliquez|appelez|kanda|hamagara|bofya|piga)\\w*")],
    ("Unexpected 'password reset / was this you?' message with a link", "Message inattendu « réinitialisation du mot de passe / était-ce vous ? » avec lien", "Ubutumwa butunguranye bwa «guhindura ijambo ry'ibanga / ni wowe?» bufite link", "Ujumbe usiotarajiwa wa «kuweka upya nenosiri / ni wewe?» wenye kiungo"),
    ("Attackers imitate security alerts to make you click a fake page. If you did not ask for a reset, the safe move is to ignore the message and check inside the real app.",
     "Les attaquants imitent les alertes de sécurité pour vous faire cliquer sur une fausse page. Si vous n'avez rien demandé, le plus sûr est d'ignorer le message et de vérifier dans la vraie appli.",
     "Abagizi ba nabi bigana impuruza z'umutekano kugira ngo ukande ku rupapuro rw'impimbano. Niba utasabye guhindura, uburyo bwizewe ni ukwirengagiza ubutumwa ukagenzura muri porogaramu nyayo.",
     "Washambuliaji huiga tahadhari za usalama ili ubofye ukurasa bandia. Kama hukuomba kuweka upya, njia salama ni kupuuza ujumbe na kukagua ndani ya programu halisi."),
    D(NOLINK, ("If you are worried, open the official app yourself and change your password there.", "Si vous êtes inquiet, ouvrez vous-même l'appli officielle et changez-y votre mot de passe.", "Niba ufite impungenge, fungura wowe porogaramu yemewe uhindure ijambo ry'ibanga aho.", "Ukihofia, fungua programu rasmi mwenyewe na ubadilishe nywila huko."), PASSW))
